{
  "headline": "FDA's records show the shortage has been listed for 42 months and the labeled plant for our product was last inspected 51 days after the posting",
  "headline_cites": ["D7", "D3"],
  "sentences": [
    {
      "text": "FDA first posted the penicillin G benzathine injection shortage on 2023-04-26 and it remains current as of 2026-10-21.",
      "cites": ["E18", "D7"]
    },
    {
      "text": "The shortage has been on FDA's list for 42 months as of today.",
      "cites": ["D7"]
    },
    {
      "text": "Our product label names Pharmacia & Upjohn Company LLC (FEI 1810189) as the plant.",
      "cites": ["E13"]
    },
    {
      "text": "FDA inspection 1208260 at that plant ended 2023-06-16 with a VAI classification, and the classification letter was issued 2024-09-10 — 51 days after the shortage posting.",
      "cites": ["D3", "E12"]
    },
    {
      "text": "Corvale East and Corvale General each have 18 days of supply on hand at current usage rates.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The rule-selected alternate manufacturer is A-S Medication Solutions, which is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["D4"]
    },
    {
      "text": "Buyer should verify availability and sourcing for A-S Medication Solutions and monitor FDA updates for Pfizer's estimated recovery in 4Q 2027.",
      "cites": ["D4", "E17"]
    }
  ]
}
